def _load_embedded(key: str) -> list[str]:
    """내장된 워드리스트 하나를 줄 목록으로 복원한다. 없는 키면 빈 목록(에러 아님,
    선택한 카테고리에 해당 서브셋이 아예 없을 수 있어 조용히 건너뛰는 게 맞음)."""
    blob = _EMBEDDED_WORDLISTS.get(key)
    if not blob:
        return []
    raw = gzip.decompress(base64.b85decode(blob)).decode("utf-8", errors="replace")
    return [line.strip() for line in raw.splitlines() if line.strip() and not line.startswith("#")]


