# ---------------------------------------------------------------------------
# TLS / 요청 공통
# ---------------------------------------------------------------------------
def make_ssl_context(insecure: bool) -> ssl.SSLContext | None:
    """--insecure를 명시적으로 줬을 때만 인증서 검증을 끈다 (자동 폴백 없음 --
    내부망 자체서명/사설CA 인증서 대상 전용, 기본값은 항상 엄격 검증)."""
    if not insecure:
        return None
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    return ctx


class HostRateLimiter:
    def __init__(self, min_interval_seconds: float) -> None:
        self._min_interval = max(0.0, min_interval_seconds)
        self._lock = threading.Lock()
        self._last_slot: dict[str, float] = {}

    def wait(self, host_key: str) -> None:
        if self._min_interval <= 0:
            return
        with self._lock:
            now = time.monotonic()
            last = self._last_slot.get(host_key, 0.0)
            next_slot = max(now, last + self._min_interval)
            self._last_slot[host_key] = next_slot
            remaining = next_slot - now
        if remaining > 0:
            time.sleep(remaining)


class RobotsCache:
    def __init__(self, user_agent: str, timeout: int, respect: bool, ssl_context: ssl.SSLContext | None) -> None:
        self.user_agent = user_agent
        self.timeout = timeout
        self.respect = respect
        self.ssl_context = ssl_context
        self._parsers: dict[str, urllib.robotparser.RobotFileParser] = {}
        self._lock = threading.Lock()

    def allowed(self, url: str) -> bool:
        if not self.respect:
            return True
        parsed = urlparse(url)
        origin = f"{parsed.scheme}://{parsed.netloc}"
        with self._lock:
            rp = self._parsers.get(origin)
            if rp is None:
                rp = urllib.robotparser.RobotFileParser()
                rp.set_url(urljoin(origin, "/robots.txt"))
                try:
                    req = urllib.request.Request(rp.url, headers={"User-Agent": self.user_agent})
                    with urllib.request.urlopen(req, timeout=self.timeout, context=self.ssl_context) as resp:  # noqa: S310
                        raw = resp.read(65536).decode("utf-8", errors="replace")
                    rp.parse(raw.splitlines())
                except Exception:  # noqa: BLE001
                    rp.parse([])
                self._parsers[origin] = rp
        try:
            return rp.can_fetch(self.user_agent, url)
        except Exception:  # noqa: BLE001
            return True


def fetch(
    url: str, timeout: int, user_agent: str, max_retries: int, want_body: bool,
    ssl_context: ssl.SSLContext | None = None, extra_headers: dict[str, str] | None = None,
    max_body_bytes: int = MAX_BODY_BYTES,
) -> tuple[int | None, int | None, float, bytes, str | None, dict[str, str] | None]:
    """(status, content_length, elapsed_ms, body, error, response_headers)."""
    attempt = 0
    last_error: str | None = None
    while attempt <= max_retries:
        start = time.monotonic()
        try:
            headers = {"User-Agent": user_agent, **(extra_headers or {})}
            req = urllib.request.Request(url, headers=headers)
            with urllib.request.urlopen(req, timeout=timeout, context=ssl_context) as resp:  # noqa: S310
                status = resp.getcode()
                body = resp.read(max_body_bytes) if want_body else b""
                elapsed_ms = (time.monotonic() - start) * 1000
                length = len(body) if want_body else int(resp.headers.get("Content-Length", 0) or 0)
                return status, length, elapsed_ms, body, None, {k.lower(): v for k, v in resp.headers.items()}
        except urllib.error.HTTPError as exc:
            elapsed_ms = (time.monotonic() - start) * 1000
            body = exc.read(max_body_bytes) if want_body else b""
            headers = {k.lower(): v for k, v in exc.headers.items()} if exc.headers else None
            return exc.code, len(body), elapsed_ms, body, None, headers
        except (urllib.error.URLError, TimeoutError, ConnectionError, OSError) as exc:
            last_error = str(exc)
            attempt += 1
            if attempt > max_retries:
                break
            time.sleep(0.5 * attempt)
    return None, None, 0.0, b"", f"Request failed after {max_retries + 1} attempt(s): {last_error}", None


def detect_fallback_baseline(
    base_url: str, timeout: int, user_agent: str, max_retries: int, ssl_context: ssl.SSLContext | None,
    extra_headers: dict[str, str] | None = None,
) -> tuple[int, int] | None:
    """SPA 캐치올(존재하지 않는 경로에도 200 응답) 감지용 베이스라인 -- 없으면
    프로브 자체가 실패한 경우(None)."""
    probe_path = f"__nx_{uuid.uuid4().hex[:16]}__"
    url = urljoin(base_url.rstrip("/") + "/", probe_path)
    status, length, _elapsed, _body, error, _headers = fetch(url, timeout, user_agent, max_retries, False, ssl_context, extra_headers)
    if error or status is None:
        return None
    return status, length or 0


# ---------------------------------------------------------------------------
# 0단계: 루트 확인 (root-discovery)
# ---------------------------------------------------------------------------
@dataclass
class RootProbe:
    candidate: str
    marker: str
    status_code: int | None
    hit: bool


@dataclass
class RootDiscoveryResult:
    confirmed: bool  # True면 마커 200 OK로 실제 확인된 루트, False면 추정(fallback)
    root_url: str  # 끝에 '/' 포함
    matched_marker: str | None
    probes: list[RootProbe] = field(default_factory=list)
    sitemap_seed_urls: list[str] = field(default_factory=list)


def _build_root_candidates(start_url: str) -> list[str]:
    """주어진 URL 경로부터 상위 경로로 거슬러 올라가는 후보 + 도메인 루트/원래 경로
    바로 아래 흔한 마운트 경로 추측을 뒤에 덧붙인다. 순서 = 우선순위(먼저 나온 후보가
    먼저 확인됨)."""
    parsed = urlparse(start_url)
    origin = f"{parsed.scheme}://{parsed.netloc}"
    segments = [s for s in parsed.path.split("/") if s]

    candidates: list[str] = []
    seen: set[str] = set()
    for i in range(len(segments), -1, -1):
        cand = origin + "/" + "/".join(segments[:i]) + ("/" if segments[:i] else "")
        if cand not in seen:
            seen.add(cand)
            candidates.append(cand)

    # 그래도 못 찾았을 때를 위한 "루트가 더 깊은 곳에 있을 수도 있다" 추측 -- 주어진
    # 경로와 도메인 루트 바로 한 단계 아래만 소수 정예로 확인(무한 깊이 아님).
    deep_bases = [origin + "/" + "/".join(segments) + ("/" if segments else "")] if segments else []
    deep_bases.append(origin + "/")
    for base in deep_bases:
        for guess in DEEP_ROOT_GUESS_PATHS:
            cand = urljoin(base, guess + "/")
            if cand not in seen:
                seen.add(cand)
                candidates.append(cand)
    return candidates


def discover_root(
    start_url: str, *, timeout: int, user_agent: str, max_retries: int, ssl_context: ssl.SSLContext | None,
    rate_limiter: HostRateLimiter, robots: RobotsCache, extra_headers: dict[str, str] | None, budget: int,
) -> RootDiscoveryResult:
    candidates = _build_root_candidates(start_url)
    probes: list[RootProbe] = []
    spent = 0
    for cand in candidates:
        hit_marker: str | None = None
        for marker in ROOT_MARKER_FILES:
            if spent >= budget:
                break
            url = urljoin(cand, marker)
            if not robots.allowed(url):
                continue
            host_key = urlparse(url).hostname or url
            rate_limiter.wait(host_key)
            status, _len, _el, _body, error, _headers = fetch(url, timeout, user_agent, max_retries, False, ssl_context, extra_headers)
            spent += 1
            ok = bool(status and status == 200 and not error)
            probes.append(RootProbe(candidate=cand, marker=marker, status_code=status, hit=ok))
            if ok:
                hit_marker = marker
                break
        if hit_marker:
            return RootDiscoveryResult(confirmed=True, root_url=cand, matched_marker=hit_marker, probes=probes)
        if spent >= budget:
            break
    # 아무 데서도 마커를 못 찾음 -- 입력 경로를 "미확인 추정 루트"로 그대로 사용.
    parsed = urlparse(start_url)
    fallback_root = f"{parsed.scheme}://{parsed.netloc}" + (parsed.path if parsed.path.endswith("/") else parsed.path + "/")
    return RootDiscoveryResult(confirmed=False, root_url=fallback_root, matched_marker=None, probes=probes)


_SITEMAP_LOC_RE = re.compile(r"<loc>\s*([^<\s]+)\s*</loc>", re.IGNORECASE)
_SITEMAP_INDEX_RE = re.compile(r"<sitemapindex", re.IGNORECASE)
MAX_SITEMAP_FILES = 20
MAX_SITEMAP_SEEDS = 500
MAX_SITEMAP_BYTES = 2 * 1024 * 1024


def discover_sitemaps(
    root_url: str, *, timeout: int, user_agent: str, max_retries: int, ssl_context: ssl.SSLContext | None,
    rate_limiter: HostRateLimiter, robots: RobotsCache, extra_headers: dict[str, str] | None,
) -> list[str]:
    """robots.txt의 Sitemap: 지시자 + 루트 직하 sitemap.xml/sitemap_index.xml을
    확인해(sitemap 인덱스면 재귀로 하위 sitemap까지, 최대 깊이 2·최대 파일 수
    MAX_SITEMAP_FILES) 크롤링 시드로 쓸 페이지 URL 목록을 모은다. 전부 best-effort --
    sitemap이 전혀 없어도 에러가 아니라 빈 목록을 반환."""
    candidate_sitemap_urls: list[str] = []
    origin = urljoin(root_url, "/")
    try:
        status, _len, _el, body, error, _h = fetch(urljoin(origin, "robots.txt"), timeout, user_agent, max_retries, True, ssl_context, extra_headers)
        if status == 200 and not error:
            text = body.decode("utf-8", errors="replace")
            for line in text.splitlines():
                if line.strip().lower().startswith("sitemap:"):
                    candidate_sitemap_urls.append(line.split(":", 1)[1].strip())
    except Exception:  # noqa: BLE001
        pass
    for guess in ("sitemap.xml", "sitemap_index.xml"):
        candidate_sitemap_urls.append(urljoin(root_url, guess))

    seen_sitemaps: set[str] = set()
    seeds: list[str] = []
    seen_seeds: set[str] = set()
    queue = [u for u in candidate_sitemap_urls if u not in seen_sitemaps]
    depth = 0
    fetched = 0
    while queue and depth < 2 and fetched < MAX_SITEMAP_FILES:
        next_queue: list[str] = []
        for sm_url in queue:
            if sm_url in seen_sitemaps or fetched >= MAX_SITEMAP_FILES:
                continue
            seen_sitemaps.add(sm_url)
            if not robots.allowed(sm_url):
                continue
            host_key = urlparse(sm_url).hostname or sm_url
            rate_limiter.wait(host_key)
            status, _len, _el, body, error, _h = fetch(sm_url, timeout, user_agent, max_retries, True, ssl_context, extra_headers, MAX_SITEMAP_BYTES)
            fetched += 1
            if status != 200 or error or not body:
                continue
            text = body.decode("utf-8", errors="replace")
            locs = _SITEMAP_LOC_RE.findall(text)
            if _SITEMAP_INDEX_RE.search(text[:200]):
                next_queue.extend(l for l in locs if l not in seen_sitemaps)
            else:
                for loc in locs:
                    if loc not in seen_seeds and len(seeds) < MAX_SITEMAP_SEEDS:
                        seen_seeds.add(loc)
                        seeds.append(loc)
        queue = next_queue
        depth += 1
    return seeds


# ---------------------------------------------------------------------------
# URL 정규화 (crawl 단계용 -- 비-ASCII href/hostname 안전 처리)
# ---------------------------------------------------------------------------
def _percent_encode_if_needed(component: str, safe: str) -> str:
    try:
        component.encode("ascii")
        return component
    except UnicodeEncodeError:
        return quote(component, safe=safe)


def _encode_netloc(netloc: str) -> str:
    try:
        netloc.encode("ascii")
        return netloc
    except UnicodeEncodeError:
        pass
    userinfo, _, hostport = netloc.rpartition("@")
    host, sep, port = hostport.partition(":")
    try:
        host = host.encode("idna").decode("ascii")
    except UnicodeError:
        host = quote(host)
    hostport = host + sep + port
    return f"{userinfo}@{hostport}" if userinfo else hostport


def ensure_ascii_safe_url(url: str) -> str:
    parsed = urlparse(url)
    netloc = _encode_netloc(parsed.netloc)
    path = _percent_encode_if_needed(parsed.path, safe="/%:@!$&'()*+,;=")
    query = _percent_encode_if_needed(parsed.query, safe="/%:@!$&'()*+,;=?")
    return urlunparse((parsed.scheme, netloc, path, parsed.params, query, parsed.fragment))


def normalize_url(url: str) -> str:
    parsed = urlparse(ensure_ascii_safe_url(url))
    path = parsed.path or "/"
    return urlunparse((parsed.scheme, parsed.netloc.lower(), path, parsed.params, parsed.query, ""))


def is_http_url(url: str) -> bool:
    return urlparse(url).scheme in ("http", "https")


def same_registrable_host(url_a: str, url_b: str) -> bool:
    return urlparse(url_a).hostname == urlparse(url_b).hostname


# ---------------------------------------------------------------------------
# 결과 모델
# ---------------------------------------------------------------------------
@dataclass
class ProbeResult:
    category: str
    url: str
    status_code: int | None = None
    content_length: int | None = None
    response_time_ms: float | None = None
    error: str | None = None
    matched_signature: str | None = None
    payload: str | None = None

    def to_dict(self) -> dict:
        return dict(self.__dict__)


class _PageParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.title_parts: list[str] = []
        self._in_title = False
        self.links: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag == "title":
            self._in_title = True
        attr_dict = dict(attrs)
        if tag == "a" and attr_dict.get("href"):
            self.links.append(attr_dict["href"])
        elif tag == "link" and attr_dict.get("href"):
            self.links.append(attr_dict["href"])

    def handle_endtag(self, tag: str) -> None:
        if tag == "title":
            self._in_title = False

    def handle_data(self, data: str) -> None:
        if self._in_title:
            self.title_parts.append(data)

    @property
    def title(self) -> str | None:
        text = "".join(self.title_parts).strip()
        return text or None


def parse_html(body: str) -> tuple[str | None, list[str]]:
    parser = _PageParser()
    try:
        parser.feed(body)
    except Exception:  # noqa: BLE001
        pass
    return parser.title, parser.links


@dataclass
class PageResult:
    url: str
    depth: int
    status_code: int | None = None
    content_type: str | None = None
    title: str | None = None
    content_length: int | None = None
    response_time_ms: float | None = None
    outbound_link_count: int = 0
    error: str | None = None
    source: str = "crawl"
    discovered_links: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {k: v for k, v in self.__dict__.items() if k != "discovered_links"}


def fetch_page(
    url: str, depth: int, timeout: int, user_agent: str, max_retries: int, ssl_context: ssl.SSLContext | None,
    extra_headers: dict[str, str] | None = None,
) -> PageResult:
    url = ensure_ascii_safe_url(url)
    status, length, elapsed_ms, body, error, headers = fetch(
        url, timeout, user_agent, max_retries, True, ssl_context, {"Accept": "text/html,*/*", **(extra_headers or {})}, MAX_CRAWL_BODY_BYTES,
    )
    if error or status is None:
        return PageResult(url=url, depth=depth, error=error)
    content_type = (headers or {}).get("content-type", "")
    title = None
    links: list[str] = []
    if "text/html" in content_type.lower() and body:
        body_text = body.decode("utf-8", errors="replace")
        title, raw_links = parse_html(body_text)
        links = [urljoin(url, link) for link in raw_links if link and not link.startswith(("javascript:", "mailto:", "tel:", "#"))]
    return PageResult(
        url=url, depth=depth, status_code=status,
        content_type=content_type.split(";")[0].strip() or None, title=title,
        content_length=length, response_time_ms=round(elapsed_ms, 1),
        outbound_link_count=len(links), discovered_links=links,
        error=f"HTTP {status}" if status and status >= 400 else None,
    )


# ---------------------------------------------------------------------------
# 공용 rate-limited 배치 fetch
# ---------------------------------------------------------------------------
def _fetch_probe_batch(
    jobs: list[tuple[str, str, str | None]],
    rate_limiter: HostRateLimiter, robots: RobotsCache, max_workers: int, timeout: int, max_retries: int,
    user_agent: str, want_body: bool, signature_check: bool, ssl_context: ssl.SSLContext | None,
    extra_headers: dict[str, str] | None = None,
) -> list[ProbeResult]:
    def _one(job: tuple[str, str, str | None]) -> ProbeResult:
        category, url, payload = job
        if not robots.allowed(url):
            return ProbeResult(category=category, url=url, error="Disallowed by robots.txt", payload=payload)
        host_key = urlparse(url).hostname or url
        rate_limiter.wait(host_key)
        status, length, elapsed_ms, body, error, _headers = fetch(url, timeout, user_agent, max_retries, want_body, ssl_context, extra_headers)
        matched = None
        if signature_check and body:
            text = body.decode("utf-8", errors="replace")
            for sig_label, pattern in TRAVERSAL_SIGNATURES.items():
                if pattern.search(text):
                    matched = sig_label
                    break
        return ProbeResult(category=category, url=url, status_code=status, content_length=length, response_time_ms=round(elapsed_ms, 1), error=error, matched_signature=matched, payload=payload)

    results: list[ProbeResult] = []
    with ThreadPoolExecutor(max_workers=max(1, min(max_workers, 10))) as pool:
        futures = {pool.submit(_one, job): job for job in jobs}
        for fut in as_completed(futures):
            results.append(fut.result())
    return results


def _fetch_page_batch(
    urls: list[str], depth: int, rate_limiter: HostRateLimiter, robots: RobotsCache, max_workers: int,
    timeout: int, max_retries: int, user_agent: str, ssl_context: ssl.SSLContext | None,
    extra_headers: dict[str, str] | None = None,
) -> list[PageResult]:
    def _one(url: str) -> PageResult:
        if not robots.allowed(url):
            return PageResult(url=url, depth=depth, error="Disallowed by robots.txt")
        host_key = urlparse(url).hostname or url
        rate_limiter.wait(host_key)
        return fetch_page(url, depth, timeout, user_agent, max_retries, ssl_context, extra_headers)

    results: list[PageResult] = []
    with ThreadPoolExecutor(max_workers=max(1, min(max_workers, 10))) as pool:
        futures = {pool.submit(_one, u): u for u in urls}
        for fut in as_completed(futures):
            results.append(fut.result())
    return results


def _is_hit(r: ProbeResult, baseline: tuple[int, int] | None) -> bool:
    if not r.status_code or r.status_code == 404:
        return False
    if baseline is not None and (r.status_code, r.content_length or 0) == baseline:
        return False
    return True


# ---------------------------------------------------------------------------
# 2단계: 기본 파일 / 백업 파일 탐색
# ---------------------------------------------------------------------------
def build_fingerprint_targets(techs: list[str], include_generic: bool) -> list[tuple[str, str]]:
    targets: list[tuple[str, str]] = []
    for tech in techs:
        builtin = BUILTIN_TECH_PATHS.get(tech)
        if builtin is not None:
            targets.extend((tech, p) for p in builtin)
            continue
        keys = TECH_WORDLIST_KEYS.get(tech)
        if keys is None:
            logger.warning("알 수 없는 --tech 값: %s (가능: %s)", tech, ", ".join([*TECH_WORDLIST_KEYS, *BUILTIN_TECH_PATHS]))
            continue
        seen: set[str] = set()
        for key in keys:
            for line in _load_embedded(key):
                if line not in seen:
                    seen.add(line)
                    targets.append((tech, line))
    if include_generic:
        seen_generic: set[str] = set(GENERIC_DEFAULT_PATHS)
        merged = list(GENERIC_DEFAULT_PATHS)
        for line in _load_embedded(GENERIC_EXTRA_KEY):
            if line not in seen_generic:
                seen_generic.add(line)
                merged.append(line)
        targets.extend(("generic", p) for p in merged)
    return targets


def run_default_scan_phase(
    root_url: str, args: argparse.Namespace, rate_limiter: HostRateLimiter, robots: RobotsCache,
    ssl_context: ssl.SSLContext | None, extra_headers: dict[str, str], budget: int,
) -> tuple[list[ProbeResult], tuple[int, int] | None, int]:
    """반환: (결과, SPA 캐치올 베이스라인, 사용한 요청 수)."""
    baseline = detect_fallback_baseline(root_url, args.timeout, args.user_agent, args.retries, ssl_context, extra_headers)
    spent = 1
    if baseline and baseline[0] != 404:
        logger.warning("존재하지 않는 경로에도 %s(%dB)로 응답함(SPA 캐치올 추정) -- 동일 결과는 히트에서 제외", *baseline)
    techs = [t.strip().lower() for t in args.tech.split(",") if t.strip()]
    targets = build_fingerprint_targets(techs, not args.no_generic)
    remaining = max(budget - spent, 0)
    if len(targets) > remaining:
        logger.warning("기본 파일 목록(%d) > 남은 예산(%d) -- 잘라냄", len(targets), remaining)
        targets = targets[:remaining]
    jobs = [(cat, urljoin(root_url, path), None) for cat, path in targets]
    logger.info("[기본 파일] %d개 경로 확인 (기술: %s)", len(jobs), ", ".join(techs) + (", generic" if not args.no_generic else ""))
    results = _fetch_probe_batch(jobs, rate_limiter, robots, args.workers, args.timeout, args.retries, args.user_agent, False, False, ssl_context, extra_headers)
    spent += len(results)

    if args.mutate and spent < budget:
        hits = [r for r in results if _is_hit(r, baseline)]
        remaining = budget - spent
        mutate_jobs = [("backup-mutation", r.url + suf, None) for r in hits for suf in BACKUP_SUFFIXES][:remaining]
        if mutate_jobs:
            logger.info("[백업 변형] 발견된 %d개 경로의 백업 확장자 변형 %d개 확인", len(hits), len(mutate_jobs))
            mut_results = _fetch_probe_batch(mutate_jobs, rate_limiter, robots, args.workers, args.timeout, args.retries, args.user_agent, False, False, ssl_context, extra_headers)
            results.extend(mut_results)
            spent += len(mut_results)
    return results, baseline, spent


# ---------------------------------------------------------------------------
# 3단계: 경로순회 / LFI 퍼징
# ---------------------------------------------------------------------------
def mutate_traversal_payload(payload: str) -> list[str]:
    variants = [payload]
    if "/" in payload or "." in payload:
        single = payload.replace("/", "%2f").replace(".", "%2e")
        if single != payload:
            variants.append(single)
        double = payload.replace("/", "%252f").replace(".", "%252e")
        if double != payload:
            variants.append(double)
    if "../" in payload:
        variants.append(payload.replace("../", "..%c0%af"))
    variants.append(payload + "%00")
    return variants


def load_traversal_payloads(target_os: str, limit: int, bypass_encodings: bool) -> list[tuple[str, str]]:
    payloads: list[tuple[str, str]] = []
    for key in FLAT_TRAVERSAL_KEYS:
        payloads.extend(("flat", line) for line in _load_embedded(key))

    os_list = ["unix", "windows"] if target_os == "both" else [target_os]
    template_payloads: list[tuple[str, str]] = []
    for key in TEMPLATE_TRAVERSAL_KEYS:
        for line in _load_embedded(key):
            for os_name in os_list:
                for target_file in TRAVERSAL_TARGET_FILES[os_name]:
                    template_payloads.append((os_name, line.replace("{FILE}", target_file)))

    if bypass_encodings:
        for label, base in template_payloads:
            for variant in mutate_traversal_payload(base):
                payloads.append((label, variant))
    else:
        payloads.extend(template_payloads)

    seen: set[str] = set()
    unique = [pl for pl in payloads if not (pl[1] in seen or seen.add(pl[1]))]
    if len(unique) > limit:
        logger.warning("경로순회 페이로드 %d개 -> --traversal-limit %d로 잘라냄", len(unique), limit)
        unique = unique[:limit]
    return unique


def run_traversal_phase(
    root_url: str, args: argparse.Namespace, rate_limiter: HostRateLimiter, robots: RobotsCache,
    ssl_context: ssl.SSLContext | None, extra_headers: dict[str, str], budget: int,
) -> list[ProbeResult]:
    payload_pairs = load_traversal_payloads(args.target_os, min(args.traversal_limit, budget), not args.no_bypass_encodings)
    if args.traversal_url_template:
        jobs = [("traversal", root_url.rstrip("/").replace("FUZZ", payload), payload) for _, payload in payload_pairs]
    else:
        base = root_url.rstrip("/")
        jobs = [("traversal", f"{base}?{args.traversal_param}={payload}", payload) for _, payload in payload_pairs]
    logger.info("[경로순회] %d개 페이로드 확인 (대상 OS: %s)", len(jobs), args.target_os)
    return _fetch_probe_batch(jobs, rate_limiter, robots, args.workers, args.timeout, args.retries, args.user_agent, True, True, ssl_context, extra_headers)


# ---------------------------------------------------------------------------
# 4단계: 링크 크롤링 (BFS) + 워드리스트
# ---------------------------------------------------------------------------
TERMINATION_MAX_DEPTH = "설정한 최대 깊이에 도달함"
TERMINATION_NO_LINKS = "다음 단계에서 방문할 링크가 발견되지 않음"
TERMINATION_OUT_OF_SCOPE = "동일 대상 범위 밖의 링크만 발견됨"
TERMINATION_ROBOTS = "robots.txt에 의해 다음 링크가 제외됨"
TERMINATION_MAX_PAGES = "최대 페이지 수에 도달함"
TERMINATION_REQUEST_ERROR = "요청 오류로 다음 링크를 수집하지 못함"


@dataclass
class CrawlStats:
    reached_depth: int = 0
    pages_by_depth: dict[int, int] = field(default_factory=dict)
    termination_reason: str = TERMINATION_MAX_DEPTH
    external_skipped: int = 0

    def to_dict(self) -> dict:
        return {
            "reached_depth": self.reached_depth,
            "pages_by_depth": dict(sorted(self.pages_by_depth.items())),
            "termination_reason": self.termination_reason,
            "external_skipped": self.external_skipped,
        }


def run_crawl_phase(
    seed_urls: list[str], args: argparse.Namespace, rate_limiter: HostRateLimiter, robots: RobotsCache,
    ssl_context: ssl.SSLContext | None, extra_headers: dict[str, str], budget: int,
) -> tuple[list[PageResult], CrawlStats]:
    seeds = [normalize_url(u) for u in seed_urls]
    visited: set[str] = set(seeds)
    results: list[PageResult] = []
    current_level = list(dict.fromkeys(seeds))
    depth = 0
    stats = CrawlStats()
    max_pages = min(args.crawl_max_pages, budget) if args.crawl_max_pages else budget

    while current_level and depth <= args.crawl_depth and len(results) < max_pages:
        remaining = max_pages - len(results)
        batch = current_level[:remaining]
        batch_results = _fetch_page_batch(batch, depth, rate_limiter, robots, args.workers, args.timeout, args.retries, args.user_agent, ssl_context, extra_headers)
        robots_disallowed = other_errors = 0
        next_candidates: list[str] = []
        for result in batch_results:
            results.append(result)
            if result.error and result.error.startswith("Disallowed"):
                robots_disallowed += 1
            elif result.error:
                other_errors += 1
            next_candidates.extend(result.discovered_links)
        stats.pages_by_depth[depth] = stats.pages_by_depth.get(depth, 0) + len(batch_results)
        stats.reached_depth = depth

        if len(results) >= max_pages:
            stats.termination_reason = TERMINATION_MAX_PAGES
            break
        depth += 1
        if depth > args.crawl_depth:
            stats.termination_reason = TERMINATION_MAX_DEPTH
            break

        next_level: list[str] = []
        external_count = 0
        for link in next_candidates:
            if not is_http_url(link):
                continue
            norm = normalize_url(link)
            if norm in visited:
                continue
            if not args.allow_external and not same_registrable_host(norm, seeds[0]):
                external_count += 1
                continue
            visited.add(norm)
            next_level.append(norm)
        stats.external_skipped += external_count
        current_level = next_level
        if not next_level:
            fetched_ok = len(batch_results) - robots_disallowed - other_errors
            if fetched_ok == 0 and robots_disallowed > 0 and other_errors == 0:
                stats.termination_reason = TERMINATION_ROBOTS
            elif fetched_ok == 0 and other_errors > 0:
                stats.termination_reason = TERMINATION_REQUEST_ERROR
            elif next_candidates and external_count == len(next_candidates):
                stats.termination_reason = TERMINATION_OUT_OF_SCOPE
            else:
                stats.termination_reason = TERMINATION_NO_LINKS
            break

    if args.crawl_wordlist:
        wl_paths: list[str] = []
        seen_wl: set[str] = set()
        for name in args.crawl_wordlist:
            key = CRAWL_WORDLIST_KEYS.get(name)
            lines = _load_embedded(key) if key else []
            if not lines:
                try:
                    with open(name, encoding="utf-8", errors="replace") as fh:
                        lines = [ln.strip() for ln in fh if ln.strip() and not ln.startswith("#")]
                except OSError:
                    logger.warning("워드리스트를 찾을 수 없음(내장 목록도, 파일로도): %s", name)
            for line in lines:
                if line not in seen_wl:
                    seen_wl.add(line)
                    wl_paths.append(line)
        if len(wl_paths) > args.crawl_wordlist_limit:
            logger.warning("워드리스트 %d개 -> --crawl-wordlist-limit %d로 잘라냄", len(wl_paths), args.crawl_wordlist_limit)
            wl_paths = wl_paths[: args.crawl_wordlist_limit]
        urls = [urljoin(seeds[0], p.lstrip("/")) for p in wl_paths]
        logger.info("[워드리스트] %d개 경로 확인", len(urls))
        wl_results = _fetch_page_batch(urls, 0, rate_limiter, robots, args.workers, args.timeout, args.retries, args.user_agent, ssl_context, extra_headers)
        for r in wl_results:
            r.source = "wordlist"
        results.extend(wl_results)

    return results, stats


# ---------------------------------------------------------------------------
# 대상 1개 전체 파이프라인
# ---------------------------------------------------------------------------
@dataclass
class TargetReport:
    target: str
    root: RootDiscoveryResult
    default_results: list[ProbeResult] = field(default_factory=list)
    default_baseline: tuple[int, int] | None = None
    traversal_results: list[ProbeResult] = field(default_factory=list)
    crawl_results: list[PageResult] = field(default_factory=list)
    crawl_stats: CrawlStats | None = None
    error: str | None = None


def run_target(target: str, args: argparse.Namespace) -> TargetReport:
    ssl_context = make_ssl_context(args.insecure)
    rate_limiter = HostRateLimiter(args.min_interval)
    robots = RobotsCache(args.user_agent, args.timeout, not args.ignore_robots, ssl_context)
    extra_headers: dict[str, str] = {}
    if args.cookies:
        extra_headers["Cookie"] = args.cookies
    for h in args.headers:
        if ":" in h:
            k, v = h.split(":", 1)
            extra_headers[k.strip()] = v.strip()

    budget = 10**9 if args.max_requests == 0 else args.max_requests

    if args.no_root_discovery:
        parsed = urlparse(target)
        root_path = parsed.path if parsed.path.endswith("/") else parsed.path + "/"
        root = RootDiscoveryResult(confirmed=True, root_url=f"{parsed.scheme}://{parsed.netloc}{root_path}", matched_marker=None)
    else:
        root_budget = min(budget, 100)
        root = discover_root(
            target, timeout=args.timeout, user_agent=args.user_agent, max_retries=args.retries,
            ssl_context=ssl_context, rate_limiter=rate_limiter, robots=robots, extra_headers=extra_headers, budget=root_budget,
        )
        budget -= len(root.probes)
        logger.info(
            "[루트 확인] %s -- %s", root.root_url,
            f"{root.matched_marker} 확인됨 (200 OK)" if root.confirmed else "마커 못 찾음, 입력 경로를 추정 루트로 사용",
        )

    seed_urls = [root.root_url]
    if not args.no_sitemap:
        sitemap_seeds = discover_sitemaps(
            root.root_url, timeout=args.timeout, user_agent=args.user_agent, max_retries=args.retries,
            ssl_context=ssl_context, rate_limiter=rate_limiter, robots=robots, extra_headers=extra_headers,
        )
        if sitemap_seeds:
            logger.info("[sitemap] %d개 URL을 크롤링 시드로 추가", len(sitemap_seeds))
            seed_urls.extend(sitemap_seeds)
        root.sitemap_seed_urls = sitemap_seeds

    phases = [p.strip() for p in args.phases.split(",") if p.strip()]
    report = TargetReport(target=target, root=root)

    def _run_phase(phase: str, phase_budget: int) -> None:
        if phase == "default":
            report.default_results, report.default_baseline, _ = run_default_scan_phase(root.root_url, args, rate_limiter, robots, ssl_context, extra_headers, phase_budget)
        elif phase == "traversal":
            report.traversal_results = run_traversal_phase(root.root_url, args, rate_limiter, robots, ssl_context, extra_headers, phase_budget)
        elif phase == "crawl":
            report.crawl_results, report.crawl_stats = run_crawl_phase(seed_urls, args, rate_limiter, robots, ssl_context, extra_headers, phase_budget)
        else:
            logger.warning("알 수 없는 --phases 값: %s (가능: default,traversal,crawl)", phase)

    per_phase_budget = max(budget // max(len(phases), 1), 1)
    if args.phase_concurrency <= 1 or len(phases) <= 1:
        for phase in phases:
            _run_phase(phase, per_phase_budget)
    else:
        with ThreadPoolExecutor(max_workers=max(1, min(args.phase_concurrency, len(phases)))) as pool:
            futures = [pool.submit(_run_phase, phase, per_phase_budget) for phase in phases]
            for fut in as_completed(futures):
                fut.result()
    return report


# ---------------------------------------------------------------------------
# 리포트
# ---------------------------------------------------------------------------
def print_target_report(report: TargetReport) -> None:
    print("=" * 70)
    print(f" 대상: {report.target}")
    print("=" * 70)
    root = report.root
    status = f"확인됨 (마커: {root.matched_marker})" if root.confirmed else "미확인 -- 추정 루트로 진행"
    print(f"[루트] {root.root_url}  [{status}]")
    if root.sitemap_seed_urls:
        print(f"  sitemap에서 크롤링 시드 {len(root.sitemap_seed_urls)}개 추가 확인됨")

    if report.default_results:
        by_cat: dict[str, list[ProbeResult]] = {}
        for r in report.default_results:
            by_cat.setdefault(r.category, []).append(r)
        for cat, items in by_cat.items():
            interesting = [r for r in items if _is_hit(r, report.default_baseline)]
            print(f"\n[기본/백업 파일 -- {cat}] ({len(items)}개 확인, {len(interesting)}개 발견)")
            for r in sorted(interesting, key=lambda r: (r.status_code or 0, r.url)):
                print(f"  {r.status_code:<4} {r.content_length or 0:>8}B  {r.url}")

    if report.traversal_results:
        interesting = [r for r in report.traversal_results if r.matched_signature]
        print(f"\n[경로순회] ({len(report.traversal_results)}개 페이로드, {len(interesting)}개 시그니처 일치)")
        for r in interesting:
            print(f"  일치({r.matched_signature})  {r.status_code}  {r.url}")

    if report.crawl_results:
        crawled = [r for r in report.crawl_results if r.source == "crawl"]
        wordlist = [r for r in report.crawl_results if r.source == "wordlist"]
        ok = sum(1 for r in crawled if r.status_code and 200 <= r.status_code < 400)
        print(f"\n[크롤링] 총 {len(crawled)}개 페이지 (정상/리다이렉트 {ok}, 오류 {len(crawled) - ok})")
        if report.crawl_stats:
            print(f"  도달 깊이: {report.crawl_stats.reached_depth}, 종료 이유: {report.crawl_stats.termination_reason}")
            if report.crawl_stats.external_skipped:
                print(f"  범위 밖(다른 도메인) 건너뜀: {report.crawl_stats.external_skipped}개")
        if wordlist:
            interesting = [r for r in wordlist if r.status_code and r.status_code != 404]
            print(f"  [워드리스트] {len(wordlist)}개 확인, {len(interesting)}개 non-404")
            for r in sorted(interesting, key=lambda r: (r.status_code or 0, r.url)):
                print(f"    {r.status_code:<4} {r.url}")
        failed = [r for r in report.crawl_results if r.error]
        if failed:
            robots_skipped = [r for r in failed if r.error and r.error.startswith("Disallowed")]
            other_failed = [r for r in failed if r not in robots_skipped]
            print(f"  [수집 실패/건너뜀] robots.txt 차단 {len(robots_skipped)}건, 그 외 오류 {len(other_failed)}건")


def _target_to_dict(report: TargetReport) -> dict:
    return {
        "target": report.target,
        "root": {
            "confirmed": report.root.confirmed,
            "root_url": report.root.root_url,
            "matched_marker": report.root.matched_marker,
            "sitemap_seed_count": len(report.root.sitemap_seed_urls),
            "probes": [p.__dict__ for p in report.root.probes],
        },
        "default_results": [r.to_dict() | {"hit": _is_hit(r, report.default_baseline)} for r in report.default_results],
        "traversal_results": [r.to_dict() | {"hit": bool(r.matched_signature)} for r in report.traversal_results],
        "crawl_results": [r.to_dict() for r in report.crawl_results],
        "crawl_stats": report.crawl_stats.to_dict() if report.crawl_stats else None,
    }


def write_json_report(reports: list[TargetReport], path: str | None) -> str:
    payload = [_target_to_dict(r) for r in reports]
    text = json.dumps(payload, indent=2, ensure_ascii=False)
    if path:
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(text)
    return text


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------
def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="recon_toolkit",
        description="정찰 올인원 스캐너 -- 루트 확인 -> 기본/백업 파일 -> 경로순회 -> 링크 크롤링을 하나로 통합.",
    )
    parser.add_argument("targets", nargs="+", help="대상 URL (1개 또는 여러 개, 공백으로 구분 -- 인프라를 모르면 1개로 폭넓게, 알면 웹서버/WAS 등 N개를 명시적으로 나열)")
    parser.add_argument("--insecure", action="store_true", help="TLS 인증서 검증을 건너뜀 (내부망 자체서명/사설CA 인증서 대상 전용 -- 명시적으로 켜야만 적용됨, 기본은 항상 엄격 검증)")

    parser.add_argument("--no-root-discovery", action="store_true", help="0단계(루트 확인)를 건너뛰고 입력 URL 경로를 그대로 루트로 사용")
    parser.add_argument("--no-sitemap", action="store_true", help="sitemap.xml 탐색/크롤링 시드 보강을 건너뜀")

    parser.add_argument("--phases", default="default,traversal,crawl", help="실행할 단계, 쉼표 구분 (기본: default,traversal,crawl 전부). 가능: default(기본/백업 파일), traversal(경로순회/LFI), crawl(링크 크롤링)")
    parser.add_argument("--phase-concurrency", type=int, default=1, help="선택한 단계 중 몇 개를 동시에 돌릴지 (기본 1=순차, 최대 3)")
    parser.add_argument("--target-concurrency", type=int, default=1, help="대상을 몇 개씩 동시에 돌릴지 (기본 1=순차, 대상 개수와 10 중 작은 값까지)")

    parser.add_argument("--tech", default="tomcat,apache,nginx", help="(default 단계) 확인할 기술 스택, 쉼표 구분. 가능: " + ", ".join([*TECH_WORDLIST_KEYS, *BUILTIN_TECH_PATHS]))
    parser.add_argument("--no-generic", action="store_true", help="(default 단계) 내장 generic 민감파일 목록(.env, .git/HEAD 등) 제외")
    parser.add_argument("--mutate", action="store_true", help="(default 단계) 발견된 경로의 백업 확장자 변형(.bak/.old/~ 등)도 확인")

    parser.add_argument("--traversal-param", default="file", help="(traversal 단계) 페이로드를 넣을 쿼리 파라미터명 (기본 file)")
    parser.add_argument("--traversal-url-template", action="store_true", help="(traversal 단계) 루트 URL 안의 리터럴 FUZZ 문자열을 페이로드로 치환 (파라미터 방식 대신)")
    parser.add_argument("--target-os", choices=["unix", "windows", "both"], default="both", help="(traversal 단계) 대상 OS (기본 both)")
    parser.add_argument("--traversal-limit", type=int, default=300, help="(traversal 단계) 최대 페이로드 수 (기본 300)")
    parser.add_argument("--no-bypass-encodings", action="store_true", help="(traversal 단계) WAF 우회 인코딩 변형(단일/이중 URL인코딩, 오버롱 UTF-8, null byte) 끄기 -- 기본은 켜짐")

    parser.add_argument("--crawl-depth", type=int, default=1, help="(crawl 단계) 최대 링크 추적 깊이 (기본 1)")
    parser.add_argument("--crawl-max-pages", type=int, default=100, help="(crawl 단계) 최대 수집 페이지 수 (기본 100, 0=예산 전체)")
    parser.add_argument("--crawl-wordlist", action="append", default=[], help="(crawl 단계) 경로 탐색용 워드리스트 짧은 이름(내장: " + ", ".join(CRAWL_WORDLIST_KEYS) + ") 또는 파일 경로, 반복 가능")
    parser.add_argument("--crawl-wordlist-limit", type=int, default=200, help="(crawl 단계) 워드리스트에서 실제 확인할 최대 경로 수 (기본 200)")
    parser.add_argument("--allow-external", action="store_true", help="(crawl 단계) 다른 도메인으로 나가는 링크도 추적 (기본은 같은 호스트만)")

    parser.add_argument("--workers", type=int, default=3, help="동시 요청 수 (기본 3, 최대 10)")
    parser.add_argument("--min-interval", type=float, default=0.5, help="같은 호스트에 대한 요청 사이 최소 간격, 초 단위 (기본 0.5)")
    parser.add_argument("--timeout", type=int, default=10, help="요청 1건당 타임아웃, 초 단위 (기본 10)")
    parser.add_argument("--retries", type=int, default=1, help="네트워크 오류 시 재시도 횟수 (기본 1)")
    parser.add_argument("--max-requests", type=int, default=1000, help="대상 1개당 전체 요청 수 상한 (기본 1000, 0=제한 없음)")
    parser.add_argument("--ignore-robots", action="store_true", help="robots.txt 무시 (기본은 준수)")
    parser.add_argument("--user-agent", default=DEFAULT_USER_AGENT, help="커스텀 User-Agent 문자열")
    parser.add_argument("--cookies", default=None, help="모든 요청에 실어 보낼 Cookie 헤더, 'k=v; k2=v2' 형식")
    parser.add_argument("--headers", action="append", default=[], help="모든 요청에 추가할 헤더 'Name: value' (반복 가능)")
    parser.add_argument("--output", choices=["console", "json"], default="console", help="출력 형식 (기본 console)")
    parser.add_argument("--output-file", default=None, help="JSON 리포트를 저장할 파일 경로")
    parser.add_argument("--force", action="store_true", help="안전상한 초과를 허용")
    parser.add_argument("-v", "--verbose", action="store_true", help="상세 로그 출력")
    return parser


def _ask_yes_no(prompt: str, default: bool = False) -> bool:
    suffix = "Y/n" if default else "y/N"
    v = input(f"{prompt} ({suffix}): ").strip().lower()
    return default if not v else v in ("y", "yes")


def _ask_int_range(prompt: str, lo: int, hi: int, default: int) -> int:
    while True:
        v = input(f"{prompt} [{lo}~{hi}, 기본 {default}]: ").strip()
        if not v:
            return default
        try:
            n = int(v)
        except ValueError:
            print(f"  정수를 입력하세요 ({lo}~{hi}).")
            continue
        if not (lo <= n <= hi):
            print(f"  {lo}~{hi} 범위 안에서 입력하세요.")
            continue
        return n


def _guided_wizard(parser: argparse.ArgumentParser) -> list[str] | None:
    print("\n=== recon_toolkit 간단 모드 ===")
    print("(대상/네트워크 상태/모드만 순서대로 입력 -> 실행)\n")

    print("대상이 하나(인프라 정보를 모름 -- 폭넓게 스캔)인가요, 아니면 여러 개(웹서버/WAS 등 알고 있는 구성요소를 각각 지정)인가요?")
    targets: list[str] = []
    while True:
        t = input(f"  대상 URL #{len(targets) + 1} (빈 줄=입력 종료): ").strip()
        if not t:
            if targets:
                break
            print("  최소 1개는 입력해야 합니다.")
            continue
        targets.append(t)

    argv: list[str] = list(targets)

    if len(targets) > 1:
        tc = _ask_int_range(f"대상 {len(targets)}개 중 몇 개를 동시에 돌릴까요?", 1, min(len(targets), 10), 1)
        argv += ["--target-concurrency", str(tc)]

    if _ask_yes_no("내부망 대상이라 TLS 인증서가 자체서명/사설CA라서 검증을 건너뛰어야 하나요?"):
        argv.append("--insecure")

    cookie = input("세션 쿠키 (로그인 후 검사 시, 없으면 Enter): ").strip()
    if cookie:
        argv += ["--cookies", cookie]

    print("\n단계(모드) 선택: default(기본/백업 파일), traversal(경로순회/LFI), crawl(링크 크롤링)")
    picked: list[str] = []
    for phase, label in [("default", "기본/백업 파일 탐색"), ("traversal", "경로순회/LFI 퍼징"), ("crawl", "링크 크롤링")]:
        if _ask_yes_no(f"  {phase} -- {label} 실행할까요?", default=True):
            picked.append(phase)
    if not picked:
        print("취소됨 (최소 1개 단계는 선택해야 합니다).")
        return None
    argv += ["--phases", ",".join(picked)]
    if len(picked) > 1:
        pc = _ask_int_range(f"선택한 {len(picked)}개 단계 중 몇 개를 동시에 돌릴까요?", 1, len(picked), 1)
        argv += ["--phase-concurrency", str(pc)]

    interval = input("요청 간격(초, 같은 호스트 기준, 빈 줄=기본 0.5): ").strip()
    if interval:
        argv += ["--min-interval", interval]

    if _ask_yes_no("고급 옵션(--tech, --traversal-limit, --crawl-depth 등)을 추가로 지정할까요?"):
        print(f"  --help 로 전체 옵션을 확인하거나, 지금 바로 추가 인자를 입력하세요 (예: --tech tomcat,nginx --mutate).")
        extra = input("  추가 인자: ").strip()
        if extra:
            import shlex
            argv += shlex.split(extra)

    return argv


def main(argv: list[str] | None = None) -> int:
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8")
        except (AttributeError, ValueError):
            pass

    parser = build_arg_parser()
    args = parser.parse_args(argv)
    logging.basicConfig(level=logging.DEBUG if args.verbose else logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s", datefmt="%H:%M:%S", stream=sys.stderr)

    for t in args.targets:
        if urlparse(t).scheme not in ("http", "https"):
            logger.error("대상 URL은 http:// 또는 https://로 시작해야 함: %r", t)
            return 2

    if not (1 <= args.phase_concurrency <= 3):
        logger.error("--phase-concurrency는 1~3 사이여야 함")
        return 2
    if args.target_concurrency < 1:
        logger.error("--target-concurrency는 1 이상이어야 함")
        return 2
    if args.max_requests > MAX_TOTAL_REQUESTS and not args.force:
        logger.error("--max-requests %d가 안전상한 %d를 넘음 (--force로 허용)", args.max_requests, MAX_TOTAL_REQUESTS)
        return 2

    target_concurrency = min(args.target_concurrency, len(args.targets), 10)
    reports: list[TargetReport] = []
    if target_concurrency <= 1:
        for t in args.targets:
            reports.append(run_target(t, args))
    else:
        with ThreadPoolExecutor(max_workers=target_concurrency) as pool:
            futures = {pool.submit(run_target, t, args): t for t in args.targets}
            for fut in as_completed(futures):
                reports.append(fut.result())

    if args.output == "json":
        text = write_json_report(reports, args.output_file)
        if not args.output_file:
            print(text)
        else:
            logger.info("JSON 리포트 저장됨: %s", args.output_file)
    else:
        for report in reports:
            print_target_report(report)
        if args.output_file:
            write_json_report(reports, args.output_file)
            logger.info("JSON 리포트도 추가로 저장됨: %s", args.output_file)
    return 0


if __name__ == "__main__":
    for _stream in (sys.stdout, sys.stderr):
        try:
            _stream.reconfigure(encoding="utf-8")
        except (AttributeError, ValueError):
            pass
    if len(sys.argv) == 1:
        try:
            _argv = _guided_wizard(build_arg_parser())
        except (EOFError, KeyboardInterrupt):
            print("\n입력이 중단됨 -- 취소됨.")
            raise SystemExit(130)
        if _argv is None:
            print("취소됨.")
            raise SystemExit(0)
        raise SystemExit(main(_argv))
    raise SystemExit(main())
